heatLayer:
const heat = heatLayer(points, {
  mode: "both",
  backend: "auto",
  evaluation: "static",
  worker: true,
  labels: true,
  step: "auto",
  bands: true,
  cover: true,
  interactive: true
}).addTo(map);

// getHoveredFeature() отдаёт типизированный объект под курсором:
// в контексте tooltip он лежит в data со статическим типом unknown.
heat.bindTooltip(() => {
  const feature = heat.getHoveredFeature();
  if (!feature) return "";
  return feature.kind === "line"
    ? `Изолиния: ${feature.fieldValue.toFixed(1)}`
    : `Зона: ${feature.lowerValue.toFixed(1)}–${feature.upperValue?.toFixed(1) ?? "∞"}`;
});

