popupConditionMatches:
// Условие проверяется на том же контексте, который получает содержимое попапа,
// поэтому и оценивать его удобнее внутри callback: там контекст уже настоящий.
marker(center).bindPopup((context) => {
  const enriched = { ...context, data: { status: "active", orders: 42 } };
  const active = popupConditionMatches({ field: "status", equals: "active" }, enriched);
  const many = popupConditionMatches({ field: "orders", greaterThan: 100 }, enriched);
  return `Активен: ${active} · Заказов больше 100: ${many}`;
}).addTo(map).openPopup();

