buildClusterIndex:
import { buildClusterIndex, queryClusterLayout } from "orihon";

const coords = new Float64Array(points.length * 2);
points.forEach((p, i) => { coords[i * 2] = p.lat; coords[i * 2 + 1] = p.lng; });
const index = buildClusterIndex({
  ids: points.map((_, i) => i),
  coords,
  gridSize: 60,
  minPoints: 2,
  clusterize: true,
  clusterMaxZoom: 16
});
showResult({ points: points.length, nodes: index.nodeCount, leaves: index.leafCount });

