webglSymbolLayer:
import { webglSymbolLayer } from "orihon";

const canvas = document.createElement("canvas");
canvas.width = canvas.height = 16;
const ctx = canvas.getContext("2d");
ctx.fillStyle = "#43d5c7";
ctx.beginPath();
ctx.arc(8, 8, 7, 0, Math.PI * 2);
ctx.fill();
const layer = webglSymbolLayer().addTo(map);
await layer.setAtlas({ dot: await createImageBitmap(canvas) });
layer.setInstances(points.slice(0, 500).map((p) => ({ lat: p.lat, lng: p.lng, symbol: "dot", size: 14 })));
showResult(layer.getStats?.() ?? { note: "Слой символов добавлен" });

createSuggestProvider:
import { createSuggestProvider } from "orihon";

const provider = createSuggestProvider(async (query, { signal }) => {
  // Здесь был бы сетевой запрос; в примере — локальная выборка.
  await new Promise((resolve) => setTimeout(resolve, 50));
  signal?.throwIfAborted?.();
  return ["Москва", "Мурманск", "Мытищи"].filter((name) => name.toLowerCase().startsWith(query.toLowerCase()));
}, { debounceMs: 120, minLength: 2 });
const items = await provider.suggest("Мо");
showResult(items);

