buildClusterLayout:
import { buildClusterLayout } from "orihon";

// Вход — колонки, а не массив объектов: ids и упакованные пары lat/lng.
const ids = points.map((point, index) => index);
const coords = new Float64Array(points.length * 2);
points.forEach((point, index) => {
  coords[index * 2] = point.lat;
  coords[index * 2 + 1] = point.lng;
});

const layout = buildClusterLayout({
  ids,
  coords,
  zoomBucket: Math.round(map.getZoom()),
  gridSize: 60,
  minPoints: 2,
  clusterize: true,
  clusterMaxZoom: 16
});
showResult({ clusters: layout.clusters.length, singles: layout.singles.length });

