// Пары — когда координаты пишут руками: скобки группируют широту с долготой.
const route = latLngs([[55.75, 37.62], [56.33, 44.00], [59.94, 30.31]]);
polyline(route, { stroke: "#43d5c7", strokeWidth: 4 }).addTo(map);

// Плоский список — когда числа уже пришли из воркера, CSV или бинарного ответа.
const packed = Float64Array.of(55.75, 37.62, 56.33, 44.00, 59.94, 30.31);
const same = latLngs(packed);

map.fitBounds(route, { padding: 40 });
showResult({ points: route.length, sameAsPacked: same[0].equals(route[0]) });

